-- Table: ALERTAS_ADMIN
CREATE TABLE "ALERTAS_ADMIN" (
    "ID_ALERTA" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE NOT NULL ENABLE,
    "ID_PROPIEDAD" NUMBER NOT NULL ENABLE,
    "TIPO_ALERTA" VARCHAR2(50) NOT NULL ENABLE,
    "NUMERO_APARTAMENTO" VARCHAR2(50),
    "NOMBRE_RESIDENTE" VARCHAR2(100),
    "ESTADO_CUOTA" VARCHAR2(50),
    "MENSAJE" VARCHAR2(500) NOT NULL ENABLE,
    "FECHA_CREACION" TIMESTAMP (6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL ENABLE,
    "LEIDA" CHAR(1) DEFAULT 'N' NOT NULL ENABLE
);

-- ============================================================================
-- 3. VISTAS DEL SISTEMA
-- ============================================================================
CREATE OR REPLACE VIEW VW_PROPUNIDAD_PORCENTAJE_TOTAL AS
SELECT id_unidad, SUM(porcentaje_propiedad) AS porcentaje_total_activo
FROM PROPIETARIOS_UNIDAD
WHERE estado = 'ACTIVO'
GROUP BY id_unidad;
/

