CREATE EDITIONABLE TRIGGER TRG_AUDITORIA_INMUTABLE
BEFORE UPDATE OR DELETE ON AUDITORIA_LOG
FOR EACH ROW
BEGIN
    RAISE_APPLICATION_ERROR(-20099, 'Seguridad: No est permitido modificar o eliminar registros de auditora (inmutabilidad estricta obligatoria).');
END;
/

ALTER TRIGGER "TRG_AUDITORIA_INMUTABLE" ENABLE;

ALTER TRIGGER "TRG_AUDITORIA_INMUTABLE" 
  COMPILE 
    PLSQL_OPTIMIZE_LEVEL=  2
    PLSQL_CODE_TYPE=  INTERPRETED    PLSCOPE_SETTINGS=  'IDENTIFIERS:NONE'
;
CREATE EDITIONABLE TRIGGER TRG_ASIGNACION_VALIDA_SCOPE
    BEFORE INSERT OR UPDATE ON USUARIO_ASIGNACIONES
    FOR EACH ROW
DECLARE
    v_alcance ROLES.alcance%TYPE;
BEGIN
    SELECT alcance INTO v_alcance FROM ROLES WHERE id_rol = :NEW.id_rol;

    IF v_alcance = 'GLOBAL' THEN
        IF :NEW.id_organizacion IS NOT NULL OR :NEW.id_propiedad IS NOT NULL OR :NEW.id_unidad IS NOT NULL THEN
            RAISE_APPLICATION_ERROR(-20010, 'Un rol de alcance GLOBAL no debe tener organizaciÃ³n/propiedad/unidad asociada.');
        END IF;
    ELSIF v_alcance IN ('ORGANIZACION', 'PROPIEDADES_SELECCIONADAS') THEN
        IF :NEW.id_organizacion IS NULL THEN
            RAISE_APPLICATION_ERROR(-20011, 'Un rol de alcance ORGANIZACION requiere id_organizacion.');
        END IF;
    ELSIF v_alcance = 'PROPIEDAD' THEN
        IF :NEW.id_organizacion IS NULL OR :NEW.id_propiedad IS NULL THEN
            RAISE_APPLICATION_ERROR(-20012, 'Un rol de alcance PROPIEDAD requiere id_organizacion e id_propiedad.');
        END IF;
    ELSIF v_alcance = 'UNIDAD' THEN
        IF :NEW.id_organizacion IS NULL OR :NEW.id_propiedad IS NULL OR :NEW.id_unidad IS NULL THEN
            RAISE_APPLICATION_ERROR(-20013, 'Un rol de alcance UNIDAD requiere id_organizacion, id_propiedad e id_unidad.');
        END IF;
    END IF;
END;
/

ALTER TRIGGER "TRG_ASIGNACION_VALIDA_SCOPE" ENABLE;

ALTER TRIGGER "TRG_ASIGNACION_VALIDA_SCOPE" 
  COMPILE 
    PLSQL_OPTIMIZE_LEVEL=  2
    PLSQL_CODE_TYPE=  INTERPRETED    PLSCOPE_SETTINGS=  'IDENTIFIERS:NONE'
;
CREATE EDITIONABLE TRIGGER TRG_ASIGNACION_VALIDA_JERARQUIA
    BEFORE INSERT OR UPDATE ON USUARIO_ASIGNACIONES
    FOR EACH ROW
DECLARE
    v_org_de_propiedad    PROPIEDADES.id_organizacion%TYPE;
    v_propiedad_de_unidad UNIDADES.id_propiedad%TYPE;
BEGIN
    IF :NEW.id_propiedad IS NOT NULL THEN
        BEGIN
            SELECT id_organizacion INTO v_org_de_propiedad
            FROM PROPIEDADES WHERE id_propiedad = :NEW.id_propiedad;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(-20020, 'id_propiedad no existe.');
        END;

        IF :NEW.id_organizacion IS NOT NULL AND v_org_de_propiedad != :NEW.id_organizacion THEN
            RAISE_APPLICATION_ERROR(-20021, 'La propiedad indicada no pertenece a la organizaciÃ³n indicada.');
        END IF;
    END IF;

    IF :NEW.id_unidad IS NOT NULL THEN
        BEGIN
            SELECT id_propiedad INTO v_propiedad_de_unidad
            FROM UNIDADES WHERE id_unidad = :NEW.id_unidad;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(-20022, 'id_unidad no existe.');
        END;

        IF :NEW.id_propiedad IS NOT NULL AND v_propiedad_de_unidad != :NEW.id_propiedad THEN
            RAISE_APPLICATION_ERROR(-20023, 'La unidad indicada no pertenece a la propiedad indicada.');
        END IF;
    END IF;
END;
/

