CREATE EDITIONABLE TRIGGER TRG_CONTRATO_SYNC_RESIDENTES
    AFTER UPDATE OF estado ON CONTRATOS
    FOR EACH ROW
     WHEN (NEW.estado = 'ACTIVO' AND OLD.estado != 'ACTIVO') BEGIN
    MERGE INTO RESIDENTES_UNIDAD r
    USING (SELECT :NEW.id_unidad AS id_u, :NEW.id_arrendatario_principal AS id_p FROM DUAL) src
    ON (r.id_unidad = src.id_u AND r.id_persona = src.id_p)
    WHEN MATCHED THEN
        UPDATE SET r.estado = 'ACTIVO', r.tipo_residente = 'ARRENDATARIO', r.fecha_inicio = :NEW.fecha_inicio
    WHEN NOT MATCHED THEN
        INSERT (id_unidad, id_persona, tipo_residente, fecha_inicio, estado)
        VALUES (src.id_u, src.id_p, 'ARRENDATARIO', :NEW.fecha_inicio, 'ACTIVO');
END;
/

ALTER TRIGGER "TRG_CONTRATO_SYNC_RESIDENTES" ENABLE;

ALTER TRIGGER "TRG_CONTRATO_SYNC_RESIDENTES" 
  COMPILE 
    PLSQL_OPTIMIZE_LEVEL=  2
    PLSQL_CODE_TYPE=  INTERPRETED    PLSCOPE_SETTINGS=  'IDENTIFIERS:NONE'
;
CREATE EDITIONABLE TRIGGER TRG_TUTORES_VALIDA_MENOR
    BEFORE INSERT OR UPDATE ON TUTORES
    FOR EACH ROW
DECLARE
    v_fecha_nac DATE;
BEGIN
    SELECT fecha_nacimiento INTO v_fecha_nac FROM PERSONAS WHERE id_persona = :NEW.id_persona_menor;
    IF v_fecha_nac IS NULL OR MONTHS_BETWEEN(TRUNC(SYSDATE), v_fecha_nac) / 12 >= 18 THEN
        RAISE_APPLICATION_ERROR(-20040, 'id_persona_menor debe corresponder a una persona menor de edad.');
    END IF;
END;
/

ALTER TRIGGER "TRG_TUTORES_VALIDA_MENOR" ENABLE;

ALTER TRIGGER "TRG_TUTORES_VALIDA_MENOR" 
  COMPILE 
