-- 4.5 BOOTSTRAP DE IDENTIDAD INICIAL (ORGANIZACION, PROPIEDAD, PERSONA, USUARIO, SUPERADMIN)
MERGE INTO ORGANIZACIONES o
USING (SELECT 1 AS ID_ORGANIZACION, 'ORGANIZACION PRINCIPAL SAED' AS NOMBRE, 'NIT-900123456-1' AS IDENTIFICACION_FISCAL, 'admin@saed.com' AS EMAIL_CONTACTO, 'ACTIVA' AS ESTADO FROM DUAL) src
ON (o.ID_ORGANIZACION = src.ID_ORGANIZACION)
WHEN NOT MATCHED THEN
    INSERT (ID_ORGANIZACION, NOMBRE, IDENTIFICACION_FISCAL, EMAIL_CONTACTO, ESTADO)
    VALUES (src.ID_ORGANIZACION, src.NOMBRE, src.IDENTIFICACION_FISCAL, src.EMAIL_CONTACTO, src.ESTADO);

MERGE INTO PROPIEDADES p
USING (SELECT 1 AS ID_PROPIEDAD, 1 AS ID_ORGANIZACION, 1 AS ID_TIPO_PROPIEDAD, 'PROPIEDAD PRINCIPAL' AS NOMBRE, 'CALLE 100 # 15-20' AS DIRECCION, 'BOGOTA' AS CIUDAD, 'COLOMBIA' AS PAIS, 'MIXTA' AS TIPO_OCUPACION_PREDOMINANTE, 'ACTIVA' AS ESTADO FROM DUAL) src
ON (p.ID_PROPIEDAD = src.ID_PROPIEDAD)
WHEN NOT MATCHED THEN
    INSERT (ID_PROPIEDAD, ID_ORGANIZACION, ID_TIPO_PROPIEDAD, NOMBRE, DIRECCION, CIUDAD, PAIS, TIPO_OCUPACION_PREDOMINANTE, ESTADO)
    VALUES (src.ID_PROPIEDAD, src.ID_ORGANIZACION, src.ID_TIPO_PROPIEDAD, src.NOMBRE, src.DIRECCION, src.CIUDAD, src.PAIS, src.TIPO_OCUPACION_PREDOMINANTE, src.ESTADO);

MERGE INTO PERSONAS p
USING (SELECT 1 AS ID_PERSONA, 1 AS ID_TIPO_DOCUMENTO, 'DOC000' AS NUMERO_DOCUMENTO, 'NATURAL' AS TIPO_PERSONA, 'Admin' AS PRIMER_NOMBRE, 'Global' AS PRIMER_APELLIDO, 'admin_global@saed.com' AS EMAIL, 'ACTIVO' AS ESTADO FROM DUAL) src
ON (p.ID_PERSONA = src.ID_PERSONA)
WHEN NOT MATCHED THEN
    INSERT (ID_PERSONA, ID_TIPO_DOCUMENTO, NUMERO_DOCUMENTO, TIPO_PERSONA, PRIMER_NOMBRE, PRIMER_APELLIDO, EMAIL, ESTADO)
    VALUES (src.ID_PERSONA, src.ID_TIPO_DOCUMENTO, src.NUMERO_DOCUMENTO, src.TIPO_PERSONA, src.PRIMER_NOMBRE, src.PRIMER_APELLIDO, src.EMAIL, src.ESTADO);

MERGE INTO USUARIOS u
USING (SELECT 1 AS ID_USUARIO, 1 AS ID_PERSONA, 'admin_global' AS NOMBRE_USUARIO, 'admin_global@saed.com' AS EMAIL, '$2a$10$Y8yWwG2uR38jM8eIq0f6oOV3/1vM7Z13GkIefw7U9M/P0FqX3q4P3' AS HASH_PASSWORD, 'ACTIVO' AS ESTADO, 0 AS INTENTOS_FALLIDOS FROM DUAL) src
ON (u.ID_USUARIO = src.ID_USUARIO)
WHEN NOT MATCHED THEN
    INSERT (ID_USUARIO, ID_PERSONA, NOMBRE_USUARIO, EMAIL, HASH_PASSWORD, ESTADO, INTENTOS_FALLIDOS)
    VALUES (src.ID_USUARIO, src.ID_PERSONA, src.NOMBRE_USUARIO, src.EMAIL, src.HASH_PASSWORD, src.ESTADO, src.INTENTOS_FALLIDOS)
WHEN MATCHED THEN
    UPDATE SET HASH_PASSWORD = src.HASH_PASSWORD, ESTADO = 'ACTIVO', INTENTOS_FALLIDOS = 0;

MERGE INTO ADMINISTRADORES_SAED a
USING (SELECT 1 AS ID_ADMINISTRADOR_SAED, 1 AS ID_USUARIO, 'SUPERADMIN' AS NIVEL, 'ACTIVO' AS ESTADO FROM DUAL) src
ON (a.ID_ADMINISTRADOR_SAED = src.ID_ADMINISTRADOR_SAED)
WHEN NOT MATCHED THEN
    INSERT (ID_ADMINISTRADOR_SAED, ID_USUARIO, NIVEL, ESTADO)
    VALUES (src.ID_ADMINISTRADOR_SAED, src.ID_USUARIO, src.NIVEL, src.ESTADO);

MERGE INTO USUARIO_ASIGNACIONES ua
USING (SELECT 1 AS ID_ASIGNACION, 1 AS ID_USUARIO, 1 AS ID_ROL, CAST(NULL AS NUMBER) AS ID_ORGANIZACION, CAST(NULL AS NUMBER) AS ID_PROPIEDAD, CAST(NULL AS NUMBER) AS ID_UNIDAD, 'ACTIVA' AS ESTADO FROM DUAL) src
ON (ua.ID_ASIGNACION = src.ID_ASIGNACION)
WHEN NOT MATCHED THEN
    INSERT (ID_ASIGNACION, ID_USUARIO, ID_ROL, ID_ORGANIZACION, ID_PROPIEDAD, ID_UNIDAD, ESTADO)
    VALUES (src.ID_ASIGNACION, src.ID_USUARIO, src.ID_ROL, src.ID_ORGANIZACION, src.ID_PROPIEDAD, src.ID_UNIDAD, src.ESTADO);

COMMIT;
-- ============================================================================
-- 7. REGISTRO DECLARATIVO DE LAS 90 POLITICAS RLS
-- ============================================================================
DECLARE
    PROCEDURE add_rls(p_table VARCHAR2, p_policy VARCHAR2, p_fn VARCHAR2, p_stmts VARCHAR2) IS
    BEGIN
        BEGIN
            DBMS_RLS.DROP_POLICY(USER, p_table, p_policy);
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
        DBMS_RLS.ADD_POLICY(
            object_schema => USER,
            object_name => p_table,
            policy_name => p_policy,
            function_schema => USER,
            policy_function => 'PKG_SAED_SECURITY_RLS.' || p_fn,
            statement_types => p_stmts,
            update_check => TRUE,
            enable => TRUE
        );
    END;
BEGIN
    add_rls('ACCESOS_CONFIGURADOS', 'POL_RLS_PROP_ACCESOS_CONFIGU', 'FN_FILTRO_PROPIEDAD', 'SELECT,INSERT,UPDATE,DELETE');
    add_rls('ACCIONES_AUTOMATIZACION', 'POL_RLS_PROP_ACCIONES_AUTOMA', 'FN_FILTRO_PROPIEDAD', 'SELECT,INSERT,UPDATE,DELETE');
    add_rls('ACTAS_ASAMBLEA', 'POL_RLS_PROP_ACTAS_ASAMBLEA', 'FN_FILTRO_PROPIEDAD', 'SELECT,INSERT,UPDATE,DELETE');
    add_rls('ACTIVOS', 'POL_RLS_PROP_ACTIVOS', 'FN_FILTRO_PROPIEDAD', 'SELECT,INSERT,UPDATE,DELETE');
    add_rls('ADMINISTRADORES_SAED', 'POL_RLS_SEC_ADM', 'FN_FILTRO_GLOBAL_MUTATE', 'SELECT,INSERT,UPDATE,DELETE');
    add_rls('ALERTAS_ADMIN', 'POL_RLS_PROP_ALERTAS', 'FN_FILTRO_PROPIEDAD', 'SELECT,UPDATE,DELETE');
    add_rls('ASAMBLEAS', 'POL_RLS_PROP_ASAMBLEAS', 'FN_FILTRO_PROPIEDAD', 'SELECT,INSERT,UPDATE,DELETE');
    add_rls('ASIGNACIONES_PARQUEADERO', 'POL_RLS_UNI_ASIGNACIONES_PA', 'FN_FILTRO_UNIDAD', 'SELECT,INSERT,UPDATE,DELETE');
    add_rls('ASISTENCIAS_ASAMBLEA', 'POL_RLS_PROP_ASISTENCIAS_ASA', 'FN_FILTRO_PROPIEDAD', 'SELECT,INSERT,UPDATE,DELETE');
    add_rls('BLOQUEOS_ZONA', 'POL_RLS_PROP_BLOQUEOS_ZONA', 'FN_FILTRO_PROPIEDAD', 'SELECT,INSERT,UPDATE,DELETE');
    add_rls('BLOQUES', 'POL_RLS_PROP_BLOQUES', 'FN_FILTRO_PROPIEDAD', 'SELECT,INSERT,UPDATE,DELETE');
    add_rls('CARTERA', 'POL_RLS_UNI_CARTERA', 'FN_FILTRO_UNIDAD', 'SELECT,INSERT,UPDATE,DELETE');
    add_rls('CATALOGO_ZONAS', 'POL_RLS_PROP_CATALOGO_ZONAS', 'FN_FILTRO_PROPIEDAD', 'SELECT,INSERT,UPDATE,DELETE');
